const ceoEmail='rodineypatrick69@gmail.com';
const ceoLogin=showLogin;
showLogin=function(selected=loginRole){ceoLogin(selected);if(selected!=='adm')return;const configured=Boolean(data.ceoAccount);$('#loginForm input[name=email]').placeholder=ceoEmail;$('.demo-access').innerHTML=configured?'<b>CEO · Administrador principal</b><p>Entre com o e-mail e a senha cadastrados neste dispositivo.</p>':`<b>Configurar administrador principal</b><p>E-mail autorizado: ${esc(ceoEmail)}</p><button type="button" onclick="configureCEO()">Cadastrar senha do CEO neste dispositivo</button>`;$('#loginForm').onsubmit=async event=>{event.preventDefault();const fields=new FormData(event.target),email=fields.get('email').trim().toLowerCase(),password=fields.get('password');if(email!==ceoEmail||!data.ceoAccount||!await checkPassword(password,data.ceoAccount.password)){$('#loginError').hidden=false;$('#loginError').textContent=configured?'E-mail ou senha inválidos.':'Cadastre primeiro a senha do CEO neste dispositivo.';return}sessionStorage.setItem('forja-identity',JSON.stringify({role:'adm',ceo:true}));sessionStorage.setItem('forja-session','adm');enterApp('adm')}};window.showLogin=showLogin;
window.configureCEO=()=>{if(data.ceoAccount)return;modal(`<h2>Cadastrar CEO administrador</h2><p>${esc(ceoEmail)}</p><p>O CEO terá acesso a todas as configurações administrativas disponíveis: cadastro de personal, licenças, solicitações e uso vitalício.</p><p class="note">Cadastro local de demonstração. A conta não é sincronizada entre aparelhos e não substitui autenticação segura no servidor.</p><form id="ceoSetup"><label>Senha do CEO<input type="password" name="password" minlength="8" required autocomplete="new-password"></label><label>Confirmar senha<input type="password" name="confirm" minlength="8" required autocomplete="new-password"></label><p id="ceoError" role="alert" hidden></p><button class="primary">Salvar cadastro do CEO</button></form>`);$('#ceoSetup').onsubmit=async event=>{event.preventDefault();const fields=new FormData(event.target);if(fields.get('password')!==fields.get('confirm')){$('#ceoError').hidden=false;$('#ceoError').textContent='As senhas precisam ser iguais.';return}const button=event.target.querySelector('button');button.disabled=true;try{const password=await passwordRecord(fields.get('password'));if(data.ceoAccount)return;data.ceoAccount={email:ceoEmail,name:'CEO · Administrador principal',password};save();$('#modal').close();showLogin('adm');toast('Cadastro do CEO salvo neste dispositivo. Entre com sua senha.')}catch{$('#ceoError').hidden=false;$('#ceoError').textContent='Não foi possível salvar. Tente novamente.'}finally{button.disabled=false}}};
const ceoAdminScreen=adminScreen;adminScreen=function(){return `<section class="card"><span class="tag">CEO · ADMINISTRADOR PRINCIPAL</span><h2>${esc(ceoEmail)}</h2><p>Acesso a todas as configurações administrativas disponíveis neste aplicativo.</p><p class="note">${data.ceoAccount?'Senha cadastrada neste dispositivo.':'Cadastro de senha pendente. Saia e escolha Administrador para finalizar.'} O controle continua local e demonstrativo.</p></section>`+ceoAdminScreen()};
if(document.body.classList.contains('signed-out'))showLogin(loginRole);else if(role==='adm')render();
